api.paint.label("bar3", [0.15, 0.65, 0.25]);
api.paint.label("bar4", [0.8, 0.2, 0.55]);
api.paint.label("bar5", [0.8, 0.2, 0.15]);
api.paint.label("dials", [0.78, 0.8, 0.83]);
api.paint.label("powerButton", [0.8, 0.15, 0.12]);
api.paint.label("antenna", [0.16, 0.17, 0.19]);
api.paint.label("handle", [0.2, 0.2, 0.22]);
api.paint.label("feet", [0.22, 0.18, 0.14]);
return __pwModel;
